package com.bonbio.controller;
import com.bonbio.dto.Dtos.*; import com.bonbio.service.*; import jakarta.validation.Valid; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@RestController @RequestMapping("/api/produits") public class ProduitController {private final ProduitService s; private final RecetteService recettes; public ProduitController(ProduitService s,RecetteService recettes){this.s=s;this.recettes=recettes;} @GetMapping public List<ProduitResponse> all(){return s.all();} @GetMapping("/{id}") public ProduitResponse one(@PathVariable Long id){return s.one(id);} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ProduitResponse add(@Valid @RequestPart("produit") ProduitRequest r,@RequestPart(value="image",required=false) MultipartFile image){return s.save(null,r,image);} @PostMapping(consumes=MediaType.APPLICATION_JSON_VALUE) public ProduitResponse addJson(@Valid @RequestBody ProduitRequest r){return s.save(null,r,null);} @PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ProduitResponse edit(@PathVariable Long id,@Valid @RequestPart("produit") ProduitRequest r,@RequestPart(value="image",required=false) MultipartFile image){return s.save(id,r,image);} @PutMapping(value="/{id}",consumes=MediaType.APPLICATION_JSON_VALUE) public ProduitResponse editJson(@PathVariable Long id,@Valid @RequestBody ProduitRequest r){return s.save(id,r,null);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} @GetMapping("/{id}/recette") public RecetteResponse recette(@PathVariable Long id){return recettes.get(id);} @PostMapping("/{id}/recette") public RecetteResponse addRecette(@PathVariable Long id,@RequestBody RecetteRequest r){return recettes.save(id,r);} @PutMapping("/{id}/recette") public RecetteResponse editRecette(@PathVariable Long id,@RequestBody RecetteRequest r){return recettes.save(id,r);} }
